package viewer

import (
	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
	"github.com/anthnel/devdesk/internal/viewer"
)

// display is how the document is shown.
//
// One axis, and `f` is the only thing that moves along it: the document as it
// is, against the one derived view its kind has. A kind has at most one — a tree
// when it is Structured, a rendered form when it is Renderable — so the toggle
// stays binary at every moment even though there are three values here.
//
// "Plain text" is still not one of them. It is this pane with the colour off,
// and giving it a display of its own would make one screen reachable two ways —
// the shape §3.9 removed from the secret backend and the deleted `:theme`
// command took with it.
type display int

const (
	displayTree display = iota
	displayText
	displayRendered
)

// Model is the document viewer.
type Model struct {
	config *config.Config
	width  int
	height int

	// source is where the document came from, and it is kept rather than
	// discarded after the first read: reload, follow and the timestamps toggle
	// are all questions for the origin, not for the bytes.
	source  viewer.Source
	doc     viewer.Document
	loading bool
	// spinner turns while the document is being read. The load is reported in
	// the footer, so the pane keeps whatever it was already showing.
	spinner spinner.Model

	display   display
	highlight bool
	wrap      bool
	minLevel  viewer.Level
	// showTimestamps is tracked here rather than asked of the source:
	// WithTimestamps returns a new source instead of mutating one, so nothing is
	// shared with a command already in flight (Rule 110), and there is therefore
	// nothing to read the flag back off.
	showTimestamps bool

	// following re-reads the source on its own clock, into this pane. It
	// replaced a `docker logs -f` run through tea.ExecProcess, which could only
	// be left with ctrl+c — killing the application and handing the terminal
	// back in the child's mode.
	following bool
	// followGen invalidates a tick loop the user has already stopped.
	//
	// tea.Tick blocks for its whole interval, so a tick scheduled before `F`
	// turned following off still arrives after it; turning follow back on before
	// that one lands would leave two loops running and double the read rate for
	// the life of the view. A stale tick is the one that fails to match this.
	followGen int

	// The tree half.
	tree      datatable.Model[treeRow]
	collapsed map[int]bool

	// The text half. lines is the document cut into token spans; it is rebuilt
	// when the document loads and when `c` toggles, never per frame.
	lines        []docLine
	textViewport viewport.Model
	bar          components.FilterBar
	matchedLines int

	// OriginView is where esc returns to. The router sets it from whatever view
	// asked for the document.
	OriginView command.ViewType

	footer components.FooterMessage
}

// New builds an empty viewer.
//
// It exists so the router can create the view like any other — the contract test
// builds every view and asks it for a title and its shortcuts. On screen it says
// there is nothing open, which is the truth and is only ever reached by opening
// the view without a document.
func New(cfg *config.Config) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	return Model{
		spinner:      s,
		config:       cfg,
		highlight:    true,
		collapsed:    make(map[int]bool),
		tree:         datatable.New(datatable.Config[treeRow]{Columns: treeColumns(), SortColumn: -1}),
		textViewport: viewport.New(0, 0),
		bar:          components.NewFilterBar(),
		display:      displayText,
	}
}

// NewWithSource builds a viewer that will load this source when it starts.
func NewWithSource(cfg *config.Config, source viewer.Source) Model {
	m := New(cfg)
	m.source = source
	m.loading = true
	return m
}

// Name is what the header calls the document.
func (m Model) Name() string {
	if m.doc.Name != "" {
		return m.doc.Name
	}
	if m.source != nil {
		return m.source.Name()
	}
	return ""
}

// hasDocument reports whether anything has been loaded. Most of the keys and
// every shortcut but esc are conditional on it (Rule 130).
func (m Model) hasDocument() bool {
	return m.doc.Name != "" || m.doc.Text != ""
}

// structured reports whether the tree display is available at all.
func (m Model) structured() bool {
	return m.doc.Kind.Structured() && m.doc.Root != nil
}

// renderable reports whether the rendered display is available at all.
func (m Model) renderable() bool {
	return m.doc.Kind.Renderable()
}

// derived is the display this document has besides its own text, and whether it
// has one at all.
//
// One function so that `f`, the opening display and the shortcuts all read the
// same answer. Three call sites deciding it with their own switch is how a view
// ends up offering a display it will then refuse to show (Rule 130).
func (m Model) derived() (display, bool) {
	switch {
	case m.structured():
		return displayTree, true
	case m.renderable():
		return displayRendered, true
	default:
		return displayText, false
	}
}

// isLog reports whether the verbosity filter applies.
func (m Model) isLog() bool { return m.doc.Kind == viewer.KindLog }

// applyDocument installs a freshly parsed document and settles every piece of
// state that depends on it.
//
// One function rather than a handful of assignments at the call sites: a
// document arrives from a first load, from a reload and from a timestamps
// toggle, and a display left pointing at a tree that the new document does not
// have would render an empty pane with nothing to say why.
//
// It returns the footer message's expiry timer, which the caller must pass on:
// a message set without one never clears (Rule 128).
func (m *Model) applyDocument(doc viewer.Document) tea.Cmd {
	m.doc = doc
	m.loading = false
	m.collapsed = make(map[int]bool)

	// A document opens on its derived display when it has one, which is what
	// the request asked for: a .json opens as json, a .xml as xml, a .md as the
	// document it is meant to read as. `f` is there for the source.
	m.display, _ = m.derived()

	// The spans come after the display, not before: a rendered document is a
	// different token stream from its source, so which one to build is the
	// display's answer to give.
	m.lines = buildLines(doc, m.highlight, m.display == displayRendered)

	// A verbosity filter left over from a previous document would hide lines of
	// this one for a reason the user set on something else.
	if !m.isLog() {
		m.minLevel = viewer.LevelUnknown
	}
	m.syncVerbosityToken()

	m.rebuildTree()
	m.tree.GotoTop()
	m.rebuildText()

	// A followed document lands at the bottom, where the new lines are. Every
	// other arrival lands at the top: a first load, a reload and a timestamps
	// toggle are all "here is the document", and the document starts at line
	// one. Following is the one case where the interesting end is the other one,
	// and a re-read that jumped back to the top every two seconds would make the
	// pane unusable for exactly what it was turned on for.
	if m.following {
		m.textViewport.GotoBottom()
	} else {
		m.textViewport.GotoTop()
	}

	// A warning, not an error: nothing failed, the document simply cannot be
	// shown the way its name asked for.
	if doc.ParseErr != nil {
		return m.footer.Warn("Malformed " + doc.Name + " — showing text")
	}
	return nil
}

// toggleHighlight is `c`. It rebuilds the spans, which is the one thing that
// costs anything here — and the reason it is a key rather than something
// recomputed on every frame.
func (m *Model) toggleHighlight() {
	m.highlight = !m.highlight
	m.lines = buildLines(m.doc, m.highlight, m.display == displayRendered)
	m.rebuildTree()
	m.rebuildText()
}

// toggleDisplay is `f`. It does nothing for a document with no derived display,
// and the shortcut is hidden in that case rather than offered and ignored.
//
// It rebuilds the spans when it crosses the rendered boundary, because the two
// sides are not the same tokens: the rendered form is the stream with its
// markers taken out. The tree costs nothing here — it reads the parsed nodes,
// not these lines.
func (m *Model) toggleDisplay() {
	derived, ok := m.derived()
	if !ok {
		return
	}
	if m.display == derived {
		m.display = displayText
	} else {
		m.display = derived
	}

	if derived == displayRendered {
		m.lines = buildLines(m.doc, m.highlight, m.display == displayRendered)
		m.rebuildText()
		m.textViewport.GotoTop()
	}
}

// formatLabel is what the header prints: the kind and the display, and the
// filter when there is one.
func (m Model) formatLabel() string {
	if !m.hasDocument() {
		return "-"
	}
	label := m.doc.Kind.String()
	if m.structured() {
		if m.display == displayTree {
			return label + " · tree"
		}
		return label + " · text"
	}
	if m.renderable() {
		if m.display == displayRendered {
			return label + " · rendered"
		}
		return label + " · raw"
	}
	if m.isLog() && m.minLevel != viewer.LevelUnknown {
		return label + " · " + minLevelLabel(m.minLevel)
	}
	return label
}

package viewer

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/viewer"
)

// docLine is one source line, kept as the token spans it is made of.
//
// The spans are the point. Wrapping counts runes, and an ANSI escape's bytes
// count as width — the same hazard Rule 122 describes for table cells — so a
// line that has already been coloured cannot be wrapped without the cut landing
// inside an escape sequence. Keeping the line as tokens means it is wrapped
// while it is still plain and coloured afterwards, which is the only order that
// works.
type docLine struct {
	Tokens []viewer.Token
	Plain  string
	Level  viewer.Level
}

// buildLines splits a document into styled-per-line spans.
//
// It is called when the document loads, when `c` toggles and when `f` crosses
// the rendered boundary — and not otherwise: tokenising five megabytes per frame
// is not viable, and the filter and the wrap both work on the result rather than
// redoing it.
//
// `rendered` is not a second kind of highlighting, which is why it composes with
// `highlight` instead of replacing it. The markers have to be found before they
// can be taken away, so a rendered document is tokenised whatever `c` says; the
// colour is then dropped afterwards, and `c` off leaves clean prose rather than
// putting the asterisks back.
func buildLines(doc viewer.Document, highlight, rendered bool) []docLine {
	tokens := []viewer.Token{{Class: viewer.ClassText, Text: doc.Text}}
	switch {
	case rendered:
		tokens = viewer.RenderMarkdown(viewer.Tokenize(doc.Kind, doc.Text))
		if !highlight {
			tokens = flatten(tokens)
		}
	case highlight:
		tokens = viewer.Tokenize(doc.Kind, doc.Text)
	}

	lines := splitTokenLines(tokens)

	// A log's level rides on the line, not on a token. The two lists are the
	// same split of the same text — ParseLog and splitTokenLines both cut on
	// "\n" — so they line up index for index.
	for i := range lines {
		if i < len(doc.Lines) {
			lines[i].Level = doc.Lines[i].Level
		}
	}
	return lines
}

// flatten takes the classes off a stream, leaving the text exactly as it is.
//
// It is how `c` behaves in a rendered document: the markers stay gone — the
// rendering is a display, not a colouring — and what is left reads as ordinary
// prose. Classes are dropped rather than the tokens merged, because a merge
// would have to run before MarkMatches cuts them again for no gain.
func flatten(tokens []viewer.Token) []viewer.Token {
	out := make([]viewer.Token, 0, len(tokens))
	for _, token := range tokens {
		out = append(out, viewer.Token{Class: viewer.ClassText, Text: token.Text})
	}
	return out
}

// withText is a piece of a token: everything the run said about itself, over a
// shorter span of text.
//
// It is a copy rather than a fresh literal on purpose. Both of the functions
// below cut tokens up, and a literal has to name every field to keep it — which
// is how a highlight ends up working right until the line is long enough to be
// wrapped, the one case it exists for. Copying makes the omission unexpressible
// instead of something to remember for the next field anyone adds.
func withText(token viewer.Token, text string) viewer.Token {
	token.Text = text
	return token
}

// splitTokenLines cuts a document-wide token stream into one slice of tokens per
// line, splitting any token that spans a newline.
func splitTokenLines(tokens []viewer.Token) []docLine {
	var lines []docLine
	var current []viewer.Token
	var plain strings.Builder

	flush := func() {
		lines = append(lines, docLine{Tokens: current, Plain: plain.String()})
		current = nil
		plain.Reset()
	}

	for _, token := range tokens {
		parts := strings.Split(token.Text, "\n")
		for i, part := range parts {
			if i > 0 {
				flush()
			}
			if part == "" {
				continue
			}
			current = append(current, withText(token, part))
			plain.WriteString(part)
		}
	}
	flush()

	// A document ending in a newline produces a trailing empty line, which is
	// true of the text but renders as a blank row nobody asked for.
	if n := len(lines); n > 1 && lines[n-1].Plain == "" {
		lines = lines[:n-1]
	}
	return lines
}

// wrapTokens splits a line into segments no wider than width runes, cutting
// tokens where a segment ends.
//
// It breaks at the width rather than at a word boundary, for the same reason
// viewer.WrapLines does: the content here is a log line, a stack trace or a
// minified document, where the columns carry meaning.
func wrapTokens(tokens []viewer.Token, width int) [][]viewer.Token {
	if width <= 0 {
		return [][]viewer.Token{tokens}
	}

	var segments [][]viewer.Token
	var current []viewer.Token
	room := width

	for _, token := range tokens {
		runes := []rune(token.Text)
		for len(runes) > 0 {
			if room == 0 {
				segments = append(segments, current)
				current, room = nil, width
			}
			take := min(room, len(runes))
			current = append(current, withText(token, string(runes[:take])))
			runes = runes[take:]
			room -= take
		}
	}
	return append(segments, current)
}

// renderSegment paints a segment, one run at a time.
//
// A log line still reads as one piece — its level styles every run of it, so an
// ERROR is picked out at a glance, and a log has exactly one token per line
// unless a search cut it. That is the deliberate exception: an occurrence takes
// matchStyle even inside a log line, so the line comes out as level, match,
// level. A search that could not be seen in a log would be missing precisely
// where the lines are longest.
//
// Anything else is coloured by token class, with a match overriding it the same
// way.
func renderSegment(tokens []viewer.Token, level viewer.Level, isLog bool) string {
	var out strings.Builder
	for _, token := range tokens {
		out.WriteString(runStyle(token, level, isLog).Render(token.Text))
	}
	return out.String()
}

func runStyle(token viewer.Token, level viewer.Level, isLog bool) lipgloss.Style {
	switch {
	case token.Match:
		return matchStyle()
	case isLog:
		return levelStyle(level)
	default:
		return syntaxStyle(token.Class)
	}
}
package viewer

import (
	"strings"

	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/theme"
	"github.com/anthnel/devdesk/internal/viewer"
)

// rebuildText renders the text pane and hands it to the viewport.
//
// It is called when the document loads, when `c`, `w` or `v` changes, when the
// search query changes and when the width changes — and at no other time.
// View() must stay read-only (Rule 110), and re-rendering five megabytes per
// frame would not be viable even if it did not.
func (m *Model) rebuildText() {
	width := m.textViewport.Width
	query := strings.TrimSpace(m.bar.SearchQuery())
	isLog := m.doc.Kind == viewer.KindLog

	var out []string
	m.matchedLines = 0

	for _, line := range m.lines {
		if isLog && !line.Level.Passes(m.minLevel) {
			continue
		}

		// One rule decides both that a line matches and where. The filter *is*
		// the absence of an occurrence, so "a line the search kept carries at
		// least one highlight" holds by construction — two calculations for one
		// question is what scan.Categorize and SecretVerdict each had to undo.
		var ranges []viewer.Range
		if query != "" {
			if ranges = viewer.MatchRanges(line.Plain, query); len(ranges) == 0 {
				continue
			}
		}
		m.matchedLines++

		// Marking comes after the filter, so it only ever runs on the lines that
		// are about to be drawn. With no ranges it returns the slice untouched.
		tokens := viewer.MarkMatches(line.Tokens, ranges)
		segments := [][]viewer.Token{tokens}
		if m.wrap && width > 0 {
			segments = wrapTokens(tokens, width)
		}
		for _, segment := range segments {
			// Padded to the full width: lipgloss inherits no background
			// (Rule 115), so a line shorter than the pane would show the
			// terminal's own from its last character to the right margin.
			out = append(out, theme.PadWithBg(renderSegment(segment, line.Level, isLog), width))
		}
	}

	if len(out) == 0 {
		out = append(out, theme.PadWithBg(theme.DimStyle.Render(m.emptyTextMessage()), width))
	}

	m.textViewport.SetContent(strings.Join(out, "\n"))
}

// emptyTextMessage says why the pane is empty, which is never obvious: an empty
// document, a filter that matched nothing and a search that matched nothing all
// look identical, and only one of them is the user's own doing.
func (m *Model) emptyTextMessage() string {
	switch {
	case m.bar.SearchQuery() != "":
		return "No line matches " + m.bar.SearchQuery()
	case m.minLevel != viewer.LevelUnknown:
		return "No line at " + minLevelLabel(m.minLevel) + " or above"
	default:
		return "Empty document"
	}
}

// minLevelLabel is how a verbosity filter reads, in the footer token and in the
// header alike — one spelling, so the two cannot drift.
func minLevelLabel(level viewer.Level) string {
	if level == viewer.LevelUnknown {
		return "all"
	}
	return "≥ " + level.String()
}

// cycleVerbosity advances the minimum level: all, then each level in turn, then
// back to all.
//
// One key rather than four toggles, because a minimum is what "verbosity" means
// and log levels are monotone — nobody wants warn but not error. The bar shows
// it as a single token, and disappears entirely at `all` (Rule 136: no filter,
// no bar).
func (m *Model) cycleVerbosity() {
	next := viewer.LevelUnknown
	switch m.minLevel {
	case viewer.LevelUnknown:
		next = viewer.Levels[0]
	default:
		for i, level := range viewer.Levels {
			if level == m.minLevel && i+1 < len(viewer.Levels) {
				next = viewer.Levels[i+1]
			}
		}
	}
	m.minLevel = next
	m.syncVerbosityToken()
	m.rebuildText()
}

// syncVerbosityToken keeps the filter bar's token showing the level in force.
//
// The label carries the value, so SetTokens is given the active flag explicitly:
// it preserves an active state by matching labels, and "≥ warn" is not the label
// "≥ info" was.
func (m *Model) syncVerbosityToken() {
	if m.doc.Kind != viewer.KindLog || m.minLevel == viewer.LevelUnknown {
		m.bar.SetTokens(nil)
		return
	}
	m.bar.SetTokens([]components.FilterToken{{Label: minLevelLabel(m.minLevel), Active: true}})
}

package viewer

import (
	"log"
	"time"

	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/viewer"
)

// Init loads the source, if there is one.
func (m Model) Init() tea.Cmd {
	if m.source == nil {
		return nil
	}
	return tea.Batch(loadCmd(m.source), m.spinner.Tick)
}

// loadCmd fetches a source's content. Every read the viewer does goes through
// here, on a command's goroutine — Update does no I/O (Rule 110).
func loadCmd(source viewer.Source) tea.Cmd {
	return func() tea.Msg {
		data, err := source.Load()
		return DocumentLoadedMsg{
			Name:    source.Name(),
			Kind:    source.Kind(),
			Content: data,
			Err:     err,
		}
	}
}

// followTickMsg asks for the next read of a followed source. It carries the
// generation it was started for, so a loop the user has stopped cannot
// resurrect itself — see stopFollowing.
type followTickMsg struct{ gen int }

func followTickCmd(every time.Duration, gen int) tea.Cmd {
	// A non-positive interval would make tea.Tick fire without pausing and spin
	// one docker exec per frame. Refused here rather than trusted, the way the
	// ports tab refuses a hand-edited 0.
	if every <= 0 {
		every = defaultFollowInterval
	}
	return tea.Tick(every, func(time.Time) tea.Msg { return followTickMsg{gen: gen} })
}

// defaultFollowInterval is the floor a source with no sensible answer falls to.
const defaultFollowInterval = 2 * time.Second

// InEditMode keeps command mode out while the search field has the keyboard.
func (m Model) InEditMode() bool { return m.bar.InEditMode() }

// FilterBarVisible tells the router to close the viewport border into the bar
// (Rule 136).
func (m Model) FilterBarVisible() bool {
	// Every display but the tree is text, and the search belongs to all of
	// them: a rendered Markdown is searched on what it shows, which is the only
	// answer that agrees with the screen.
	return m.bar.IsVisible() && m.display != displayTree
}

func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.resize(msg.Width, msg.Height)
		return m, nil

	case tea.KeyMsg:
		return m.handleKeyMsg(msg)

	case DocumentLoadedMsg:
		return m.handleDocumentLoaded(msg)

	case PagerExitMsg:
		return m.handlePagerExit(msg)

	case followTickMsg:
		return m.handleFollowTick(msg)

	case spinner.TickMsg:
		// The chain stops when nothing is loading, and Init/reload restart it.
		if !m.loading {
			return m, nil
		}
		var cmd tea.Cmd
		m.spinner, cmd = m.spinner.Update(msg)
		m.footer.SetSpinnerFrame(m.spinner.View())
		return m, cmd
	}

	m.footer.Handle(msg)
	return m, nil
}

// resize lays out whichever half is on screen. Both are sized, not just the
// active one: a `f` between two window sizes would otherwise show a pane laid
// out for the previous width.
func (m *Model) resize(width, height int) {
	m.width = width
	m.height = height

	m.tree.Resize(width, height)

	m.textViewport.Width = width
	m.textViewport.Height = max(height, 1)
	m.bar.Resize(width)
	m.rebuildText() // the wrap and the padding both depend on the width
}

func (m Model) handleDocumentLoaded(msg DocumentLoadedMsg) (tea.Model, tea.Cmd) {
	m.loading = false
	if msg.Err != nil {
		log.Printf("ERROR [viewer] load %s: %v", msg.Name, msg.Err)
		return m, m.footer.Error(loadErrorMessage(msg.Err))
	}
	m.footer.Clear()
	return m, m.applyDocument(viewer.Open(msg.Name, msg.Kind, msg.Content))
}

// loadErrorMessage names the two refusals and hides the rest behind the log
// (Rule 128): "file is too large" is something the user can act on, an OS error
// string in a footer is not.
func loadErrorMessage(err error) string {
	switch err {
	case viewer.ErrTooLarge:
		return "File is too large to view"
	case viewer.ErrBinary:
		return "Not a text file"
	default:
		return "Failed to open — check logs"
	}
}

// handlePagerExit takes the pager's return, and says so when it failed.
//
// The report is not decoration. A pager that cannot start comes back in
// milliseconds and looks exactly like one the user quit at once, so the whole
// event is indistinguishable from `V` doing nothing — which is precisely how the
// broken Windows command line went unnoticed. The log line was already there and
// nobody reads a log to find out why a key did nothing.
func (m Model) handlePagerExit(msg PagerExitMsg) (tea.Model, tea.Cmd) {
	var report tea.Cmd
	if msg.Err != nil {
		log.Printf("ERROR [viewer] pager: %v", msg.Err)
		report = m.footer.Error("Pager failed — check logs")
	}
	// Whatever the pager showed, the document may have moved on while the TUI
	// was suspended. Reloading is the only way back to something true.
	if m.source == nil {
		return m, report
	}
	m.loading = true
	return m, tea.Batch(report, loadCmd(m.source))
}

func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.bar.InEditMode() {
		var cmd tea.Cmd
		m.bar, cmd = m.bar.Update(msg)
		m.rebuildText()
		return m, cmd
	}

	switch msg.String() {
	case "esc":
		return m.goBack()
	case "f":
		m.toggleDisplay()
		return m, nil
	case "c":
		m.toggleHighlight()
		return m, nil
	case "ctrl+r":
		return m.reload()
	}

	if m.display == displayTree {
		return m.handleTreeKey(msg)
	}
	return m.handleTextKey(msg)
}

// goBack returns to whoever opened the document. With no origin — the empty
// viewer the router builds for its own contract test — there is nowhere to go,
// and swallowing esc silently is better than switching to a view nobody asked
// for.
func (m Model) goBack() (tea.Model, tea.Cmd) {
	if m.OriginView == "" {
		return m, nil
	}
	// Leaving stops the clock. The router keeps this view, so a loop left
	// running would go on shelling out to docker every two seconds for a
	// document nobody is looking at — and the user would come back to a pane
	// that had scrolled itself to the bottom while they were gone.
	m = m.stopFollowing()
	origin := m.OriginView
	return m, func() tea.Msg { return BackToOriginMsg{Origin: origin} }
}

func (m Model) reload() (tea.Model, tea.Cmd) {
	if m.source == nil {
		return m, nil
	}
	m.loading = true
	return m, tea.Batch(loadCmd(m.source), m.spinner.Tick)
}

func (m Model) handleTreeKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "right":
		m.toggleNode(true)
		return m, nil
	case "left":
		m.toggleNode(false)
		return m, nil
	}
	return m, m.tree.Update(msg)
}

func (m Model) handleTextKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "/":
		return m, m.bar.ActivateSearch()
	case "w":
		m.wrap = !m.wrap
		m.rebuildText()
		return m, nil
	case "v":
		if !m.isLog() {
			return m, nil
		}
		m.cycleVerbosity()
		return m, nil
	case "t":
		return m.toggleTimestamps()
	case keymap.Fetch:
		return m.toggleFollow()
	case keymap.Pager:
		return m.openPager()

	// The scroll keys. `q` is deliberately absent: it is the application's quit
	// key (Rule 111), and the logs pane this replaced was the one screen that
	// swallowed it.
	case "up":
		m.textViewport.ScrollUp(1)
	case "down":
		m.textViewport.ScrollDown(1)
	case "pgup":
		m.textViewport.HalfPageUp()
	case "pgdown":
		m.textViewport.HalfPageDown()
	case "home":
		m.textViewport.GotoTop()
	case "end":
		m.textViewport.GotoBottom()
	}
	return m, nil
}

// ── The source's optional capabilities ───────────────────────────────────────
//
// Each is probed with a type assertion, the way the router probes FooterView.
// They are three single-method interfaces rather than one with three methods
// precisely so there is no half-satisfied state: CLAUDE.md's HeaderView warning
// is about a view supplying two of four methods and silently satisfying none.

// timestamps returns the source's timestamp capability, if it has one.
func (m Model) timestamps() (viewer.Timestamped, bool) {
	src, ok := m.source.(viewer.Timestamped)
	return src, ok
}

func (m Model) followable() (viewer.Followable, bool) {
	src, ok := m.source.(viewer.Followable)
	return src, ok
}

func (m Model) pageable() (viewer.Pageable, bool) {
	src, ok := m.source.(viewer.Pageable)
	return src, ok
}

// timestampsOn tracks the toggle rather than asking the source, which holds it
// but cannot be interrogated through the interface — WithTimestamps returns a
// new source rather than mutating one, so nothing is shared with a command
// already in flight (Rule 110).
func (m Model) toggleTimestamps() (tea.Model, tea.Cmd) {
	src, ok := m.timestamps()
	if !ok {
		return m, nil
	}
	m.showTimestamps = !m.showTimestamps
	m.source = src.WithTimestamps(m.showTimestamps)
	m.loading = true
	return m, loadCmd(m.source)
}

// toggleFollow is `F`. It re-reads the source on its own clock, into this pane.
//
// It used to be tea.ExecProcess over `docker logs -f`, and the defect that
// replaced it is worth keeping written down: the only way out of that process
// is ctrl+c, a suspended TUI does not intercept it, so it killed DevDesk and
// gave the terminal back in whatever mode the child had left it — after which
// keys stopped answering. A capability whose only exit kills the application is
// not one.
//
// The read is the one `ctrl+r` already does: same command, same message, same
// handler. Following is that key on a timer and nothing more, which is why it
// costs no new loading path.
func (m Model) toggleFollow() (tea.Model, tea.Cmd) {
	src, ok := m.followable()
	if !ok {
		return m, nil
	}
	if m.following {
		return m.stopFollowing(), nil
	}
	m.following = true
	m.followGen++
	// The first read is immediate. Waiting a whole interval before anything
	// moves would leave the user unsure the key did anything, and what is on
	// screen is already up to one interval old.
	return m, tea.Batch(loadCmd(m.source), followTickCmd(src.FollowInterval(), m.followGen))
}

// stopFollowing is the one place following is turned off, so no path can leave
// the flag set with no tick behind it, or a tick running with the flag clear.
func (m Model) stopFollowing() Model {
	m.following = false
	// Bumping the generation is what actually ends the loop. The tick already
	// in flight blocks for its whole interval and arrives whatever happens
	// here; the mismatch is what makes it a no-op instead of it finding the
	// flag turned back on and carrying a second loop into the new run.
	m.followGen++
	return m
}

// handleFollowTick re-reads, then schedules the next one.
//
// A stale tick — from a loop the user stopped, or restarted — returns no
// command, which is how the old loop dies rather than running beside the new.
func (m Model) handleFollowTick(msg followTickMsg) (tea.Model, tea.Cmd) {
	if !m.following || msg.gen != m.followGen || m.source == nil {
		return m, nil
	}
	src, ok := m.followable()
	if !ok {
		return m.stopFollowing(), nil
	}
	// m.loading stays false deliberately: a load is reported in the footer with
	// a spinner (Rule 139), and one blinking every two seconds would read as
	// something going wrong with the thing that is working. The follow status
	// line is what says the pane is live.
	return m, tea.Batch(loadCmd(m.source), followTickCmd(src.FollowInterval(), msg.gen))
}

// openPager hands the document to the system pager.
//
// It survives for one source and deliberately: `less` handles a gigabyte and
// follows it, which a viewport holding the whole document in memory never will.
// Every other pager path in the application is gone.
func (m Model) openPager() (tea.Model, tea.Cmd) {
	src, ok := m.pageable()
	if !ok {
		return m, nil
	}
	return m, tea.ExecProcess(src.PagerCmd(), func(err error) tea.Msg {
		return PagerExitMsg{Err: err}
	})
}

package viewer

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View renders whichever half is on screen.
func (m Model) View() string {
	contentStyle := lipgloss.NewStyle().Background(theme.ColorBackground).PaddingLeft(1)

	switch {
	case m.loading && !m.hasDocument():
		// The load says so in the footer, with a spinner. Nothing is shown here
		// because there is nothing yet to show — and a reload keeps the
		// document on screen rather than blanking it, which is the case below.
		return ""
	case !m.hasDocument():
		return contentStyle.Render(theme.HelpStyle.Render("\nNothing open\n\nOpen a file from workspaces, or inspect a container."))
	case m.display == displayTree:
		return m.tree.View()
	default:
		return m.textViewport.View()
	}
}

// GetFooterHeight is Rule 124's budget: an empty line and an info line, plus the
// filter bar when it is showing.
func (m Model) GetFooterHeight() int {
	return 2 + m.bar.ExtraHeight()
}

// RenderFooter draws the filter bar and the one line of state.
func (m Model) RenderFooter(width int) string {
	var parts []string
	if m.bar.IsVisible() {
		parts = append(parts, m.bar.View())
	}
	parts = append(parts, theme.EmptyLineBg(width), m.footer.View(width, m.status()))
	return strings.Join(parts, "\n")
}

// status is what the view derives on every frame: the read, reported here so
// the pane does not swap itself for a message.
func (m Model) status() components.Status {
	if m.loading {
		return components.Status{Text: "Loading " + m.Name() + "...", Spinner: true}
	}
	// Following is a state, not an event, so it is derived here rather than
	// posted as a footer message — one would expire after three seconds while
	// the pane went on refreshing (Rule 128). It is also the only thing on
	// screen saying the document is live: the reads themselves are deliberately
	// silent, because a spinner blinking every two seconds would read as
	// something going wrong with the thing that is working.
	if m.following {
		return components.Status{Text: "Following — " + keymap.Fetch + " to stop"}
	}
	return components.Status{}
}

// ── HeaderView ───────────────────────────────────────────────────────────────
//
// All four methods. The router probes for the interface as a whole and falls
// back in silence, so a view supplying two of them renders an empty title with
// nothing to say why — which is what happened to the configuration view.

func (m Model) GetTitle() string {
	if name := m.Name(); name != "" {
		return theme.IconCodeFile + " Viewer · " + name
	}
	return theme.IconCodeFile + " Viewer"
}

func (m Model) GetIcon() string { return "" }

func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
	info := []shortcut.HeaderInfo{
		{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
		{Key: "Format", Value: m.formatLabel(), Style: theme.HeaderValueStyle},
	}
	if !m.hasDocument() {
		return info
	}
	if m.structured() && m.display == displayTree {
		return append(info, shortcut.HeaderInfo{
			Key: "Nodes", Value: fmt.Sprintf("%d", m.doc.NodeCount()), Style: theme.HeaderValueStyle,
		})
	}
	return append(info, shortcut.HeaderInfo{
		Key: "Lines", Value: m.lineCount(), Style: theme.HeaderValueStyle,
	})
}

// lineCount says how many lines are showing, and out of how many when a filter
// is narrowing them. A bare count under an active filter would read as the size
// of the document, which is the one thing it is not.
func (m Model) lineCount() string {
	total := len(m.lines)
	if m.matchedLines == total {
		return fmt.Sprintf("%d", total)
	}
	return fmt.Sprintf("%d/%d", m.matchedLines, total)
}

// GetShortcuts is state-aware (Rule 130): every key that depends on the kind of
// document or on what its source can do is offered only when it would work.
func (m Model) GetShortcuts() shortcut.Shortcuts {
	if !m.hasDocument() {
		return []shortcut.Shortcut{{Key: "esc", Description: "Go back"}}
	}

	var shortcuts []shortcut.Shortcut

	if m.structured() {
		// ←→ collapses a node, which only the tree has — greyed in the text
		// pane rather than dropped, for the same reason as w and / below.
		inTree := m.display == displayTree
		display := "Show as tree"
		if inTree {
			display = "Show as text"
		}
		shortcuts = append(shortcuts,
			shortcut.Shortcut{Key: "←→", Description: "Collapse/Expand", Disabled: !inTree},
			shortcut.Shortcut{Key: "f", Description: display},
		)
	}

	// The same key, and the wording says which way it goes — "Show raw" on a
	// rendered document, "Show rendered" on its source.
	if m.renderable() {
		if m.display == displayRendered {
			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "f", Description: "Show raw markdown"})
		} else {
			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "f", Description: "Show rendered markdown"})
		}
	}

	// The tree is the same document seen another way, and `f` toggles between
	// the two — so the text pane's keys are greyed there rather than dropped
	// (Rule 130). Hiding them made three entries appear and disappear on every
	// press of a key whose whole job is to switch back and forth.
	//
	// What depends on the *document* rather than on the display stays out of
	// the list entirely: a Markdown file has no verbosity and never will, which
	// is a different screen's worth of difference, not a "not now".
	inTree := m.display == displayTree
	shortcuts = append(shortcuts, shortcut.Shortcut{Key: "w", Description: "Toggle wrap", Disabled: inTree})
	if m.isLog() {
		shortcuts = append(shortcuts, shortcut.Shortcut{Key: "v", Description: "Verbosity", Disabled: inTree})
	}
	shortcuts = append(shortcuts, shortcut.Shortcut{Key: "/", Description: "Search", Disabled: inTree})

	shortcuts = append(shortcuts, shortcut.Shortcut{Key: "c", Description: "Toggle coloring"})

	if _, ok := m.timestamps(); ok {
		shortcuts = append(shortcuts, shortcut.Shortcut{Key: "t", Description: "Toggle timestamps"})
	}
	if m.source != nil {
		shortcuts = append(shortcuts, shortcut.Shortcut{Key: "ctrl+r", Description: "Reload"})
	}
	if _, ok := m.followable(); ok {
		// The wording says which way the key goes, the way `f` does above.
		if m.following {
			shortcuts = append(shortcuts, shortcut.Shortcut{Key: keymap.Fetch, Description: "Stop following"})
		} else {
			shortcuts = append(shortcuts, shortcut.Shortcut{Key: keymap.Fetch, Description: "Follow live output"})
		}
	}
	if _, ok := m.pageable(); ok {
		shortcuts = append(shortcuts, shortcut.Shortcut{Key: "V", Description: "Open in system pager"})
	}

	return append(shortcuts,
		shortcut.Shortcut{Key: "esc", Description: "Go back"},
		shortcut.Shortcut{Key: "?", Description: "Help"},
	)
}

// GetHelpContent implements help.Provider (Rule 114).
func (m Model) GetHelpContent() help.Content {
	return help.Content{
		Title: "Viewer",
		Description: "A read-only view of one document. JSON and XML open on a navigable tree; " +
			"Markdown opens rendered, with its markers applied rather than shown; " +
			"YAML, TOML, Dockerfiles and shell scripts open as colored text; " +
			"logs open as text with a verbosity filter; everything else opens as text. " +
			"The viewer is opened from another view — a file in workspaces, an inspect or a log in containers — and Esc returns there.",
		KeyBindings: []help.KeyBinding{
			{Key: "↑/k", Description: "Move up"},
			{Key: "↓/j", Description: "Move down"},
			{Key: "→/l", Description: "Expand the selected node (tree)"},
			{Key: "←/h", Description: "Collapse the selected node (tree)"},
			{Key: "f", Description: "Switch between the derived view — tree, or rendered Markdown — and the source"},
			{Key: "c", Description: "Turn syntax coloring on or off"},
			{Key: "w", Description: "Soft-wrap long lines (text)"},
			{Key: "v", Description: "Cycle the minimum log level shown (logs)"},
			{Key: "/", Description: "Search the text — matching lines only, occurrences highlighted"},
			{Key: "t", Description: "Show or hide timestamps (container logs)"},
			{Key: "ctrl+r", Description: "Reload from the source"},
			{Key: "F", Description: "Follow live output — re-reads the log every 2s in this pane, and keeps the view pinned to the bottom. Press F again to stop (container logs)"},
			{Key: "V", Description: "Open in the system pager, which streams rather than polls. Leave it with 'q' (container logs)"},
			{Key: "esc", Description: "Return to the view the document was opened from"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "The source, and the view derived from it",
				Body: "f switches between the document as it is on disk and the one view its kind derives from it. " +
					"A JSON or XML document derives a tree: → expands a node, ← collapses it, and a closed container " +
					"shows how many children it holds. A Markdown document derives its rendered form: the #, the ** " +
					"and the backticks are applied as weight, italics and color instead of being shown, list bullets " +
					"become •, a quote becomes a rule down the margin, and a fenced code block keeps the coloring of " +
					"its own language. Press f again for the source, to the character. " +
					"A kind derives at most one view, so f is never ambiguous — and for a kind that derives none it " +
					"is hidden rather than offered and ignored: that covers logs, YAML, TOML, Dockerfiles and shell " +
					"scripts, all of which are colored but not walkable.",
			},
			{
				Title: "What rendering does not do",
				Body: "Links, tables and horizontal rules are shown as they are written. A link's brackets are " +
					"ordinary text to the lexer, indistinguishable from a bracket in a sentence, and this viewer " +
					"guesses at nothing — the link text and its URL are colored apart instead. Nothing is out of " +
					"reach either way: f shows the source exactly.",
			},
			{
				Title: "Coloring",
				Body: "c turns syntax coloring on and off, in the tree and in the text alike. JSON, XML, YAML, TOML, " +
					"Markdown, Dockerfiles and shell scripts are colored. A file is recognized by its extension or by " +
					"its whole name — Dockerfile, Dockerfile.dev, .bashrc — and never by what its content looks like; " +
					"the one exception is a file with no extension at all opening on a shebang, which is the file " +
					"naming its own interpreter. With coloring off the document reads as plain text, and a rendered " +
					"Markdown keeps its markers hidden: c is coloring, f is the display. Colors follow the current " +
					"theme; no document has colors of its own.",
			},
			{
				Title: "Search",
				Body: "/ searches the text. Lines with no match are hidden and the header counts what is left, so " +
					"a search reads as a filter — and every occurrence in the lines that remain is highlighted, which " +
					"is what says where the match is in a long line. The highlight is not syntax coloring: it stays " +
					"on with c off, it survives soft wrap, and in a log the line keeps its level color around it.",
			},
			{
				Title: "Log verbosity",
				Body: "v cycles the minimum level shown: all, trace, debug, info, warn, error. A line with no level " +
					"of its own inherits the level of the line above it, so a stack trace stays with the error that " +
					"raised it — filtering to 'warn and above' never breaks one apart. A line before any level at all " +
					"is always shown.",
			},
			{
				Title: "Reload and follow",
				Body: "ctrl+r re-reads the document from where it came from — the file on disk, or docker. For " +
					"container logs, ctrl+f follows live output and e opens the system pager; both suspend the TUI " +
					"until you leave them, and the document is re-read on the way back.",
			},
			{
				Title: "What will not open",
				Body: "A file over 5 MB is refused, and so is a binary one: the footer says which. A malformed JSON " +
					"or XML is not refused — it opens as text, with a note saying it would not parse, because it is " +
					"exactly the file you need to look at.",
			},
		},
	}
}

package viewer

import "strings"

// Range is a half-open byte range inside a line: [Start, End).
//
// Bytes rather than runes, because a token holds a string and slicing one by
// byte is exact and allocates nothing. The wrap counts runes, which is a
// different question and stays where it is.
type Range struct {
	Start int
	End   int
}

// MatchRanges is every place query occurs in text, case-insensitively.
//
// It is the *only* thing that decides a search matched, and it answers where at
// the same time. Nothing else may re-derive it: the filter that hides
// non-matching lines is `len(MatchRanges(...)) > 0`, so "a line that survived the
// search carries at least one highlighted occurrence" is true by construction
// rather than by two calculations agreeing. Two rules for one question is what
// scan.Categorize and Result.SecretVerdict each had to undo, and the symptom was
// the same both times — something counted in one place and absent from the other.
//
// The ranges come back in order and never overlap, which is what lets MarkMatches
// walk the tokens once.
func MatchRanges(text, query string) []Range {
	if text == "" || query == "" {
		return nil
	}

	haystack, needle := strings.ToLower(text), strings.ToLower(query)

	// The exactness guard. strings.ToLower can change a string's length in bytes
	// — 'İ' folds to two runes — and an offset into the folded text then names a
	// different byte of the original, so the highlight would land beside the
	// match. When the lengths disagree the search falls back to a case-sensitive
	// one: fewer matches, but every one of them in the right place.
	if len(haystack) != len(text) || len(needle) != len(query) {
		haystack, needle = text, query
	}

	var ranges []Range
	for from := 0; from+len(needle) <= len(haystack); {
		i := strings.Index(haystack[from:], needle)
		if i < 0 {
			break
		}
		start := from + i
		ranges = append(ranges, Range{Start: start, End: start + len(needle)})
		from = start + len(needle)
	}
	return ranges
}

// MarkMatches splits tokens at the range boundaries and marks what falls inside.
//
// The split has to happen while the text is still plain, for the reason docLine
// exists at all: a styled run cannot be cut, because the measure counts an escape
// sequence's bytes as width and the cut lands inside the sequence (Rule 122, one
// layer up). A match is therefore one more span, never a colour laid over a
// finished line.
//
// A query crosses class boundaries freely — searching `"name":` spans a string
// and a punctuation token — which is why the ranges are computed on the line's
// flat text and applied to the tokens afterwards.
//
// The invariant Tokenize promises holds here too: concatenating the result
// reproduces the input exactly.
func MarkMatches(tokens []Token, ranges []Range) []Token {
	if len(ranges) == 0 {
		return tokens
	}

	out := make([]Token, 0, len(tokens)+2*len(ranges))
	offset, next := 0, 0

	for _, token := range tokens {
		start := offset
		end := start + len(token.Text)
		offset = end

		// Ranges that closed before this token can never apply to a later one:
		// they are ordered and disjoint.
		for next < len(ranges) && ranges[next].End <= start {
			next++
		}

		pos, i := start, next
		for pos < end {
			if i >= len(ranges) || ranges[i].Start >= end {
				out = appendSpan(out, token, pos-start, end-start, false)
				break
			}
			if plainUntil := ranges[i].Start; plainUntil > pos {
				out = appendSpan(out, token, pos-start, plainUntil-start, false)
				pos = plainUntil
			}
			// A range may run past this token and into the next; it is consumed
			// only once it has actually closed.
			stop := min(ranges[i].End, end)
			out = appendSpan(out, token, pos-start, stop-start, true)
			pos = stop
			if ranges[i].End <= end {
				i++
			}
		}
	}
	return out
}

// appendSpan adds a slice of a token, keeping everything the run said about
// itself and stamping whether the search found it. It copies rather than building
// a literal so that a field added to Token later cannot be dropped here in
// silence.
//
// An empty slice is dropped: it would render as nothing and concatenate to
// nothing.
func appendSpan(out []Token, token Token, from, to int, match bool) []Token {
	if from >= to {
		return out
	}
	token.Text = token.Text[from:to]
	token.Match = match
	return append(out, token)
}
