			if len([]rune(key)) != 1 || !isLetter(key) {
				continue
			}
			if retiredAliases[key] {
				t.Errorf("%s: binds %q, a vim alias with no surviving meaning "+
					"(home/end already cover g/G)", clause.where, key)
				continue
			}
			if hasNavigation {
